        { year: "1957", title: "ПОЖАР", titleJa: "火災", description: "10-11 октября пожар в активной зоне привёл к выбросу радиоактивности", descriptionJa: "10〜11日、炉心火災により放射性物質が放出された。" },
        { year: "1957", title: "ТУШЕНИЕ", titleJa: "消火", description: "Пожар потушен заливкой воды в активную зону", descriptionJa: "炉心への注水により消火。" }
